  "message": "The change was saved, but the response could not be built in time. Read the object again instead of repeating the write.",
  "additional_data": {
    "from": "publicApi.pageObjectPointerToPageObject.beforePreload",
    "elapsed_ms": "55012",
    "deadline_ms": "55000",
    "retry_guidance": [
